import React, { useState, useEffect } from 'react';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import Box from '@mui/material/Box';
import Grid from '@mui/material/Grid';
import Drawer from '@mui/material/Drawer';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';
import Avatar from '@mui/material/Avatar';
import CircularProgress from '@mui/material/CircularProgress';
import Container from '@mui/material/Container';

// Icons
import HomeIcon from '@mui/icons-material/Home';
import ExploreIcon from '@mui/icons-material/Explore';
import SubscriptionsIcon from '@mui/icons-material/Subscriptions';
import VideoLibraryIcon from '@mui/icons-material/VideoLibrary';
import HistoryIcon from '@mui/icons-material/History';
import SummarizeIcon from '@mui/icons-material/Summarize';
import ThumbUpIcon from '@mui/icons-material/ThumbUp';
import WhatshotIcon from '@mui/icons-material/Whatshot';
import MusicNoteIcon from '@mui/icons-material/MusicNote';
import MovieIcon from '@mui/icons-material/Movie';
import SportsEsportsIcon from '@mui/icons-material/SportsEsports';
import NewspaperIcon from '@mui/icons-material/Newspaper';
import SettingsIcon from '@mui/icons-material/Settings';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import FeedbackIcon from '@mui/icons-material/Feedback';

// Components
import VideoPlayer from './components/VideoPlayer';
import SummaryDisplay from './components/SummaryDisplay';
import NotesDisplay from './components/NotesDisplay';
import Header from './components/Header';
import VideoCard from './components/VideoCard';
import RelatedVideos from './components/RelatedVideos';
import './App.css';

// Sample video data
const sampleVideos = [
  {
    id: 'dQw4w9WgXcQ',
    title: 'Rick Astley - Never Gonna Give You Up (Official Music Video)',
    channel: 'Rick Astley',
    views: '1.2B views',
    timestamp: '14 years ago',
    thumbnail: 'https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg',
  },
  {
    id: 'jNQXAC9IVRw',
    title: 'Me at the zoo',
    channel: 'jawed',
    views: '252M views',
    timestamp: '18 years ago',
    thumbnail: 'https://i.ytimg.com/vi/jNQXAC9IVRw/hqdefault.jpg',
  },
  {
    id: 'kJQP7kiw5Fk',
    title: 'Luis Fonsi - Despacito ft. Daddy Yankee',
    channel: 'Luis Fonsi',
    views: '8.1B views',
    timestamp: '7 years ago',
    thumbnail: 'https://i.ytimg.com/vi/kJQP7kiw5Fk/hqdefault.jpg',
  },
  {
    id: 'fJ9rUzIMcZQ',
    title: 'Queen - Bohemian Rhapsody (Official Video Remastered)',
    channel: 'Queen Official',
    views: '1.7B views',
    timestamp: '13 years ago',
    thumbnail: 'https://i.ytimg.com/vi/fJ9rUzIMcZQ/hqdefault.jpg',
  },
  {
    id: 'JGwWNGJdvx8',
    title: 'Ed Sheeran - Shape of You (Official Music Video)',
    channel: 'Ed Sheeran',
    views: '5.9B views',
    timestamp: '6 years ago',
    thumbnail: 'https://i.ytimg.com/vi/JGwWNGJdvx8/hqdefault.jpg',
  },
  {
    id: 'hT_nvWreIhg',
    title: 'OneRepublic - Counting Stars (Official Music Video)',
    channel: 'OneRepublic',
    views: '3.7B views',
    timestamp: '10 years ago',
    thumbnail: 'https://i.ytimg.com/vi/hT_nvWreIhg/hqdefault.jpg',
  },
  {
    id: 'YykjpeuMNEk',
    title: 'Coldplay - Hymn For The Weekend (Official Video)',
    channel: 'Coldplay',
    views: '1.8B views',
    timestamp: '7 years ago',
    thumbnail: 'https://i.ytimg.com/vi/YykjpeuMNEk/hqdefault.jpg',
  },
  {
    id: 'RgKAFK5djSk',
    title: 'Wiz Khalifa - See You Again ft. Charlie Puth [Official Video]',
    channel: 'Wiz Khalifa',
    views: '5.6B views',
    timestamp: '8 years ago',
    thumbnail: 'https://i.ytimg.com/vi/RgKAFK5djSk/hqdefault.jpg',
  }
];

const theme = createTheme({
  palette: {
    primary: {
      main: '#FF0000', // YouTube red
    },
    secondary: {
      main: '#282828', // YouTube dark gray
    },
    background: {
      default: '#F9F9F9', // YouTube light gray background
      paper: '#FFFFFF',
    },
  },
  typography: {
    fontFamily: [
      'Roboto',
      'Arial',
      'sans-serif',
    ].join(','),
  },
});

const drawerWidth = 240;

function App() {
  const [videos, setVideos] = useState(sampleVideos);
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [summary, setSummary] = useState(null);
  const [notes, setNotes] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('summary');
  const [searchQuery, setSearchQuery] = useState('');
  const [showSummaryPanel, setShowSummaryPanel] = useState(false);

  const handleVideoSelect = (video) => {
    setSelectedVideo(video);
    setShowSummaryPanel(false); // Reset summary panel when selecting a new video
    setSummary(null);
    setNotes(null);
  };

  const handleSearch = (query) => {
    setSearchQuery(query);
    // In a real app, this would call an API to search for videos
    // For now, we'll just filter our sample videos
    if (query) {
      const filteredVideos = sampleVideos.filter(video => 
        video.title.toLowerCase().includes(query.toLowerCase())
      );
      setVideos(filteredVideos);
    } else {
      setVideos(sampleVideos);
    }
  };

  const generateSummary = async () => {
    if (!selectedVideo) return;

    setLoading(true);
    setShowSummaryPanel(true);
    setSummary(null);
    setNotes(null);

    try {
      // Step 1: Get transcript
      const transcriptResponse = await fetch('/api/transcript', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ videoId: selectedVideo.id }),
      });

      const transcriptData = await transcriptResponse.json();

      if (!transcriptData.success) {
        throw new Error(transcriptData.error || 'Failed to fetch transcript');
      }

      const { transcript } = transcriptData;

      // Step 2: Generate summary
      const summaryResponse = await fetch('/api/summary', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ transcript }),
      });

      const summaryData = await summaryResponse.json();

      if (!summaryData.success) {
        throw new Error(summaryData.error || 'Failed to generate summary');
      }

      setSummary(summaryData.summary);

      // Step 3: Generate notes
      const notesResponse = await fetch('/api/notes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ transcript }),
      });

      const notesData = await notesResponse.json();

      if (!notesData.success) {
        throw new Error(notesData.error || 'Failed to generate notes');
      }

      setNotes(notesData.notes);

    } catch (error) {
      console.error('Error processing video:', error);
      alert(`Error: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleTimeClick = (time) => {
    // Find the video player iframe and set its current time
    const iframe = document.querySelector('iframe');
    if (iframe && iframe.contentWindow) {
      // Convert timestamp format (e.g., "1:30") to seconds
      const timeParts = time.split(':');
      let seconds = 0;

      if (timeParts.length === 2) {
        // Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 60 + parseInt(timeParts[1]);
      } else if (timeParts.length === 3) {
        // Hours:Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 3600 + parseInt(timeParts[1]) * 60 + parseInt(timeParts[2]);
      }

      // Use YouTube iframe API to seek to the specified time
      iframe.contentWindow.postMessage(JSON.stringify({
        event: 'command',
        func: 'seekTo',
        args: [seconds, true]
      }), '*');
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Header />
      <Container maxWidth="lg">
        <Box sx={{ my: 4 }}>
          <Typography variant="h4" component="h1" gutterBottom align="center">
            YouTube Smart Video Summary + Auto-Note Taker
          </Typography>

          <VideoInput onSubmit={handleVideoSubmit} loading={loading} />

          {videoUrl && (
            <Box sx={{ mt: 4 }}>
              <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, gap: 2 }}>
                <Box sx={{ flex: 1 }}>
                  <VideoPlayer videoId={videoId} />
                </Box>

                <Box sx={{ flex: 1 }}>
                  {loading ? (
                    <Typography>Processing video... This may take a few moments.</Typography>
                  ) : (
                    <>
                      <Box sx={{ display: 'flex', mb: 2 }}>
                        <Box 
                          onClick={() => setActiveTab('summary')}
                          sx={{ 
                            flex: 1, 
                            p: 1, 
                            textAlign: 'center', 
                            cursor: 'pointer',
                            borderBottom: activeTab === 'summary' ? '2px solid #FF0000' : 'none',
                            fontWeight: activeTab === 'summary' ? 'bold' : 'normal'
                          }}
                        >
                          Summary
                        </Box>
                        <Box 
                          onClick={() => setActiveTab('notes')}
                          sx={{ 
                            flex: 1, 
                            p: 1, 
                            textAlign: 'center', 
                            cursor: 'pointer',
                            borderBottom: activeTab === 'notes' ? '2px solid #FF0000' : 'none',
                            fontWeight: activeTab === 'notes' ? 'bold' : 'normal'
                          }}
                        >
                          Notes
                        </Box>
                      </Box>

                      {activeTab === 'summary' && summary && (
                        <SummaryDisplay summary={summary} onTimeClick={handleTimeClick} />
                      )}

                      {activeTab === 'notes' && notes && (
                        <NotesDisplay notes={notes} />
                      )}
                    </>
                  )}
                </Box>
              </Box>
            </Box>
          )}
        </Box>
      </Container>
    </ThemeProvider>
  );
}

export default App;
